#!/usr/bin/env bash
# Recadrage : la résolution réelle de la photo, un format que le navigateur sait écrire (AVIF, WebP, JPEG),
# un nom qui suit le format (un JPEG recadré n'est plus refusé), « Défaire » au doigt.
# Prérequis : apply-docs-envois.sh. Pas de migration.
# Usage (racine du repo) : bash apply-fix-recadrage.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/gallery-crop/components/Cropper.tsx" 2>/dev/null | grep -qF "PHOTO_OUTPUT_TYPES"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Toutes les portes par où un fichier entre" "apps/web/content/docs/dev/index.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-envois.sh puis apply-docs-envois.sh"; exit 1; }
MODIFIED=("apps/web/src/features/gallery-crop/components/Cropper.tsx" "apps/web/src/features/gallery-crop/types/cropper.types.ts" "apps/web/src/features/gallery-crop/hooks/useTransformWithUndo.ts" "apps/web/src/features/avatar/AvatarUploader.tsx")
CREATED=("packages/contracts/src/media/cropOutput.ts" "apps/web/src/features/gallery-crop/lib/encodeCanvas.ts" "e2e/recadrage.spec.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "packages/contracts/src/media" 2>/dev/null || true; rmdir -p "apps/web/src/features/gallery-crop/lib" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "PHOTO_OUTPUT_TYPES" "apps/web/src/features/gallery-crop/components/Cropper.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "packages/contracts/src/media"
